    plan.max_resume_builds = 1023;
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_wide_dirty_v1 requires"));
    plan.max_resume_builds = 1024;
    plan.shard = Some(ScaleShard { index: 0, count: 6 });
    assert!(plan
        .validate()
        .unwrap_err()
        .to_string()
        .contains("scale_wide_dirty_v1 requires"));
}

